<template>
  <div class="loans-list-wrapper">
    <!-- Barra de resumo -->
    <div class="summary-bar mb-3">
      <b-row align-v="center">
        <b-col md="4">
          <div class="d-flex align-items-center">
            <div class="summary-icon mr-2" :class="statusClass">
              <b-icon :icon="statusIcon" font-scale="1.1"></b-icon>
            </div>
            <div>
              <div class="summary-count">{{ loanList.length }}</div>
              <div class="summary-label text-muted">{{ loanList.length === 1 ? 'financiamento' : 'financiamentos' }}</div>
            </div>
          </div>
        </b-col>
        <b-col md="4" class="text-center">
          <div class="summary-total-label text-muted">Montante Total</div>
          <div class="summary-total-value font-weight-bold">{{ formatMoney(totalAmount) }}</div>
        </b-col>
        <b-col md="4" class="text-right">
          <b-input-group size="sm" class="search-box">
            <b-input-group-prepend is-text class="bg-light border-right-0">
              <b-icon icon="search" variant="secondary" font-scale="0.85"></b-icon>
            </b-input-group-prepend>
            <b-form-input
              type="text"
              class="border-left-0 bg-light"
              v-model="searchQuery"
              placeholder="Pesquisar..."
            ></b-form-input>
          </b-input-group>
        </b-col>
      </b-row>
    </div>

    <!-- Tabela -->
    <div v-if="filteredLoans.length === 0" class="empty-state text-center py-5">
      <b-icon icon="inbox" font-scale="2.5" class="text-muted mb-2"></b-icon>
      <p class="text-muted mb-0">Nenhum financiamento encontrado.</p>
    </div>

    <div v-else class="table-responsive">
      <table class="table table-hover table-sm loans-table mb-0">
        <thead>
          <tr class="table-header">
            <th class="pl-3" width="30">#</th>
            <th>Mutuário</th>
            <th class="text-right">Montante</th>
            <th class="text-center">Prestações</th>
            <th class="text-center">Taxa</th>
            <th class="text-center">Gestor</th>
            <th class="text-center">Data</th>
            <th class="text-center" width="60">Acção</th>
          </tr>
        </thead>
        <tbody>
          <tr
            v-for="(loan, index) in filteredLoans"
            :key="loan.id || index"
            class="loan-row"
          >
            <td class="pl-3 text-muted">{{ index + 1 }}</td>
            <td>
              <div class="d-flex align-items-center">
                <b-avatar
                  :text="getCustomerInitials(loan.accountNumber)"
                  size="32"
                  class="avatar-loan mr-2"
                  :variant="avatarVariant(index)"
                ></b-avatar>
                <div>
                  <div class="customer-name">{{ getCustomerName(loan.accountNumber) }}</div>
                  <small class="text-muted">{{ loan.accountNumber }}</small>
                </div>
              </div>
            </td>
            <td class="text-right">
              <span class="amount-value" v-money-format="loan.amount"></span>
            </td>
            <td class="text-center">
              <span class="badge badge-light border px-2">{{ loan.numberOfInstallments }} {{ loan.numberOfInstallments == 1 ? 'mês' : 'meses' }}</span>
            </td>
            <td class="text-center">
              <span class="rate-badge">{{ (loan.interestRate * 100).toFixed(0) }}%</span>
            </td>
            <td class="text-center">
              <small class="text-muted">{{ getCreditManagerName(loan.creditManager) }}</small>
            </td>
            <td class="text-center">
              <small class="text-muted" v-date-format="loan.dateCreated || loan.createdAt"></small>
            </td>
            <td class="text-center">
              <b-button
                size="sm"
                variant="link"
                class="text-primary p-0"
                @click="openCustomerPanel(loan.accountNumber)"
                v-b-tooltip.hover
                title="Ver mutuário"
              >
                <b-icon icon="box-arrow-up-right" font-scale="0.9"></b-icon>
              </b-button>
            </td>
          </tr>
        </tbody>
        <tfoot>
          <tr class="table-footer">
            <td :colspan="2" class="pl-3 font-weight-bold text-muted">Total</td>
            <td class="text-right font-weight-bold" v-money-format="filteredTotal"></td>
            <td :colspan="5"></td>
          </tr>
        </tfoot>
      </table>
    </div>
  </div>
</template>

<script>
import { mapGetters } from "vuex";
import MoneyFormat from "@/utils/moneyFormat";
import FilterCustomer from "@/utils/filterCustomer";
import moment from "moment";

export default {
  name: "LoansList",

  props: {
    selectLoanList: {
      type: Array,
      default: () => [],
    },
    listType: {
      type: String,
      default: "pending", // "pending" ou "rejected"
    },
  },

  data: () => ({
    today: moment(),
    loanList: [],
    searchQuery: "",
  }),

  created() {
    if (this.user.userRole === 1) {
      this.loanList = this.selectLoanList;
    } else {
      this.loanList = this.selectLoanList.filter(
        (a) => a.creditManager == this.user.id
      );
    }
  },

  watch: {
    selectLoanList(newVal) {
      if (this.user.userRole === 1) {
        this.loanList = newVal;
      } else {
        this.loanList = newVal.filter((a) => a.creditManager == this.user.id);
      }
    },
  },

  computed: {
    ...mapGetters([
      "isLoading",
      "user",
      "users",
      "token",
      "customers",
      "currentCustomer",
      "customerLoans",
      "customerTranzactions",
      "company",
    ]),

    filteredLoans() {
      if (!this.searchQuery.trim()) return this.loanList;
      const query = this.searchQuery.toLowerCase();
      return this.loanList.filter((loan) => {
        const customerName = this.getCustomerName(loan.accountNumber).toLowerCase();
        const accountNumber = (loan.accountNumber || "").toLowerCase();
        return customerName.includes(query) || accountNumber.includes(query);
      });
    },

    totalAmount() {
      return this.loanList.reduce((sum, l) => sum + (parseFloat(l.amount) || 0), 0);
    },

    filteredTotal() {
      return this.filteredLoans.reduce((sum, l) => sum + (parseFloat(l.amount) || 0), 0);
    },

    statusClass() {
      return this.listType === "rejected" ? "bg-soft-danger" : "bg-soft-warning";
    },

    statusIcon() {
      return this.listType === "rejected" ? "x-circle-fill" : "clock-history";
    },
  },

  methods: {
    getCustomerName(accountNumber) {
      try {
        const customer = FilterCustomer.filter(this.customers, accountNumber);
        return customer ? customer.customerName : accountNumber;
      } catch {
        return accountNumber;
      }
    },

    getCustomerInitials(accountNumber) {
      const name = this.getCustomerName(accountNumber);
      if (!name || name === accountNumber) return "?";
      const parts = name.trim().split(/\s+/);
      if (parts.length >= 2) {
        return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
      }
      return name.charAt(0).toUpperCase();
    },

    getCreditManagerName(managerId) {
      if (!managerId || !this.users || this.users.length === 0) return "—";
      const manager = this.users.find((u) => u.id == managerId);
      return manager ? manager.name : "—";
    },

    avatarVariant(index) {
      const variants = ["primary", "info", "success", "warning", "secondary"];
      return variants[index % variants.length];
    },

    formatMoney(value) {
      return MoneyFormat.formatMoney(value);
    },

    openCustomerPanel(accountNumber) {
      const filteredCustomer = this.customers.filter(
        (a) => a.accountNumber == accountNumber
      );
      if (filteredCustomer.length > 0) {
        this.$store.commit("SET_CURRENT_CUSTOMER", filteredCustomer[0]);
        this.$router.replace("/customer");
      }
    },
  },
};
</script>

<style scoped>
/* Barra de resumo */
.summary-bar {
  background: #f8f9fa;
  border-radius: 8px;
  padding: 12px 16px;
  border: 1px solid #eee;
}
.summary-icon {
  width: 40px;
  height: 40px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.bg-soft-warning { background-color: rgba(255, 193, 7, 0.12); color: #d39e00; }
.bg-soft-danger { background-color: rgba(220, 53, 69, 0.1); color: #dc3545; }
.summary-count { font-size: 1.25rem; font-weight: 700; line-height: 1.2; color: #333; }
.summary-label { font-size: 0.7rem; text-transform: uppercase; letter-spacing: 0.5px; }
.summary-total-label { font-size: 0.7rem; text-transform: uppercase; letter-spacing: 0.5px; }
.summary-total-value { font-size: 1.05rem; color: #009640; }

/* Pesquisa */
.search-box { max-width: 200px; margin-left: auto; }

/* Tabela */
.table-header th {
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: #888;
  border-top: none;
  border-bottom: 2px solid #009640;
  padding: 8px 6px;
  white-space: nowrap;
}
.loan-row td {
  font-size: 0.85rem;
  vertical-align: middle;
  padding: 10px 6px;
  border-bottom: 1px solid #f0f0f0;
}
.loan-row:hover {
  background-color: rgba(0, 150, 64, 0.04);
}
.table-footer td {
  font-size: 0.8rem;
  border-top: 2px solid #e9ecef;
  padding: 10px 6px;
}

/* Avatar */
.avatar-loan { font-size: 0.7rem; font-weight: 600; }

/* Nome */
.customer-name { font-weight: 600; font-size: 0.85rem; color: #333; line-height: 1.3; }

/* Montante */
.amount-value { font-weight: 600; color: #333; }

/* Taxa */
.rate-badge {
  display: inline-block;
  background: linear-gradient(135deg, #009640, #00b34a);
  color: white;
  font-size: 0.7rem;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: 10px;
}

/* Estado vazio */
.empty-state {
  padding: 40px 20px;
}

/* Responsivo */
@media (max-width: 768px) {
  .search-box { max-width: 100%; margin-top: 8px; }
  .summary-bar .row > div { text-align: center !important; margin-bottom: 8px; }
}
</style>
